def time_str_to_us(t_s: str) -> float:
    # t_s is a string representing a time
    # Should be [0-9\.]+([mun]?s)?
    #   ex. 300ns 23.5 .2ms
    # (This is not a perfect match, but enough for us to duck parse)
    # We need to convert it to us
    m = re.match(r"([0-9\.]+)([mun]?s)?", t_s)
    if m:
        try:
            val = float(m.group(1))
        except ValueError:
            raise ValueError(f"Can't convert {t_s} to time")
        unit = m.group(2)
        if unit == "s":
            val *= 1e6
        elif unit == "ms":
            val *= 1e3
        elif unit == "ns":
            val *= 1e-3
        return val
    else:
        raise ValueError(f"Can't convert {t_s} to time")

def search_file(self, file_name: str) -> Optional[str]:
    if os.path.isfile(file_name):
        return file_name

    # search file in $PATH
    if "PATH" in os.environ:
        if sys.platform in ["linux", "linux2", "darwin"]:
            path_sep = ":"
        elif sys.platform in ["win32"]:
            path_sep = ";"
        else:  # pragma: no cover
            return None

        for dir_name in os.environ["PATH"].split(path_sep):
            candidate = os.path.join(dir_name, file_name)
            if os.path.isfile(candidate):
                return candidate

    return None

def run(self) -> VizProcedureResult:
    if self.options.version:
        return self.show_version()
    elif self.options.attach > 0:
        return self.attach()
    elif self.options.attach_installed > 0:
        return self.attach_installed()
    elif self.options.uninstall > 0:
        return self.uninstall()
    elif self.options.cmd_string is not None:
        return self.run_string()
    elif self.options.module:
        return self.run_module()
    elif self.command:
        return self.run_command()
    elif self.options.compress:
        return self.run_compress()
    elif self.options.decompress:
        return self.run_decompress()
    elif self.options.combine:
        return self.run_combine(files=self.options.combine)
    elif self.options.align_combine:
        return self.run_combine(files=self.options.align_combine, align=True)
    else:
        self.parser.print_help()
        return True, None

def run_module(self) -> VizProcedureResult:
    import runpy
    code = "run_module(modname, run_name='__main__', alter_sys=True)"
    global_dict = {
        "run_module": runpy.run_module,
        "modname": self.options.module,
    }
    sys.argv = [self.options.module] + self.command[:]
    sys.path.insert(0, os.getcwd())
    return self.run_code(code, global_dict)

def run_compress(self):
    file_to_compress = self.options.compress
    if not file_to_compress or not os.path.exists(file_to_compress):
        return False, f"Unable to find file {file_to_compress}"

    if not file_to_compress.endswith(".json"):
        return False, "Only support compressing json report"

    if not self.options.output_file:
        output_file = "result.cvf"
    else:
        output_file = self.options.output_file

    compressor = VCompressor()

    with open(file_to_compress) as f:
        data = json.load(f)
        compressor.compress(data, output_file)

    return True, None

def run_decompress(self):
    file_to_decompress = self.options.decompress
    if not file_to_decompress or not os.path.exists(file_to_decompress):
        return False, f"Unable to find file {file_to_decompress}"

    if not self.options.output_file:
        output_file = "result.json"
    else:
        output_file = self.options.output_file

    compressor = VCompressor()

    data = compressor.decompress(file_to_decompress)

    with open(output_file, "w") as f:
        json.dump(data, f)

    return True, None

def show_version(self) -> VizProcedureResult:
    print(__version__)
    return True, None

def run_combine(self, files: List[str], align: bool = False) -> VizProcedureResult:
    options = self.options
    builder = ReportBuilder(files, align=align, minimize_memory=options.minimize_memory)
    if options.output_file:
        ofile = options.output_file
    else:
        ofile = "result.json"
    builder.save(output_file=ofile)

    return True, None

def generate_report(
        self,
        output_file: TextIO,
        output_format: str,
        file_info: bool = True) -> None:
    sub = {}
    if output_format == "html":
        self.prepare_json(file_info=file_info, display_time_unit="ns")
        with open(os.path.join(os.path.dirname(__file__), "html/trace_viewer_embedder.html"), encoding="utf-8") as f:
            tmpl = f.read()
        with open(os.path.join(os.path.dirname(__file__), "html/trace_viewer_full.html"), encoding="utf-8") as f:
            sub["trace_viewer_full"] = f.read()
        if "orjson" in sys.modules:
            sub["json_data"] = orjson.dumps(self.combined_json) \
                                     .decode("utf-8") \
                                     .replace("</script>", "<\\/script>")
        else:
            sub["json_data"] = json.dumps(self.combined_json) \
                                   .replace("</script>", "<\\/script>")
        output_file.write(Template(tmpl).substitute(sub))
    elif output_format == "json":
        self.prepare_json(file_info=file_info)
        if "orjson" in sys.modules:
            output_file.write(orjson.dumps(self.combined_json).decode("utf-8"))
        else:
            if self.minimize_memory:
                json.dump(self.combined_json, output_file)  # type: ignore
            else:
                output_file.write(json.dumps(self.combined_json))

def save(self, output_file: Union[str, TextIO] = "result.html", file_info: bool = True) -> None:
    if isinstance(output_file, str):
        file_type = output_file.split(".")[-1]

        if file_type == "html":
            with open(output_file, "w", encoding="utf-8") as f:
                self.generate_report(f, output_format="html", file_info=file_info)
        elif file_type == "json":
            with open(output_file, "w", encoding="utf-8") as f:
                self.generate_report(f, output_format="json", file_info=file_info)
        elif file_type == "gz":
            with gzip.open(output_file, "wt") as f:
                self.generate_report(f, output_format="json", file_info=file_info)
        else:
            raise Exception("Only html, json and gz are supported")
    else:
        self.generate_report(output_file, output_format="json", file_info=file_info)

    if isinstance(output_file, str):
        self.final_messages.append(("view_command", {"output_file": os.path.abspath(output_file)}))

    self.print_messages()

def print_messages(self):
    if self.verbose > 0:
        same_line_print("")
        for msg_type, msg_args in self.final_messages:
            if msg_type == "overflow":
                print("")
                color_print("WARNING", ("Circular buffer is full, you lost some early data, "
                                        "but you still have the most recent data."))
                color_print("WARNING", ("    If you need more buffer, use \"viztracer --tracer_entries <entry_number>\""))
                color_print("WARNING", "    Or, you can try the filter options to filter out some data you don't need")
                color_print("WARNING", "    use --quiet to shut me up")
                print("")
            elif msg_type == "total_entries":
                print(f"Total Entries: {msg_args['total_entries']}")
            elif msg_type == "view_command":
                report_abspath = os.path.abspath(msg_args["output_file"])
                print("Use the following command to open the report:")
                if " " in report_abspath:
                    color_print("OKGREEN", f"vizviewer \"{report_abspath}\"")
                else:
                    color_print("OKGREEN", f"vizviewer {report_abspath}")

