            with open(self.path, encoding="utf-8", errors="ignore") as f:
                trace_data = json.load(f)
            fg = FlameGraph(trace_data)
            self.fg_data = fg.dump_to_perfetto()
            Handler = functools.partial(PerfettoHandler, self)
        else:
            print(f"Do not support flamegraph for file type {filename}")
            return 1
    elif filename.endswith("json"):
        trace_data = None
        if self.use_external_procesor:
            Handler = functools.partial(ExternalProcessorHandler, self)
            self.externel_processor_process = ExternalProcessorProcess(self.path)
        else:
            with open(self.path, encoding="utf-8", errors="ignore") as f:
                trace_data = json.load(f)
                self.file_info = trace_data.get("file_info", {})
            Handler = functools.partial(PerfettoHandler, self)
    elif filename.endswith("html"):
        Handler = functools.partial(HtmlHandler, self)
    else:
        print(f"Do not support file type {filename}")
        return 1

    if self.is_port_in_use():
        print(f'Error! Port {self.port} is already in use, try another port with "--port"')
        return 1

    socketserver.TCPServer.allow_reuse_address = True
    with VizViewerTCPServer(('0.0.0.0', self.port), Handler) as self.httpd:
        if not self.once and not self.quiet:
            print("Running vizviewer")
            print(f"You can also view your trace on http://localhost:{self.port}")
            print("Press Ctrl+C to quit", flush=True)
        self.ready.set()
        if self.once:
            self.httpd.timeout = self.timeout
            while not self.httpd.__dict__.get("trace_served", False):
                self.httpd.handle_request()
        else:
            self.httpd.serve_forever()

    if self.externel_processor_process is not None:
        self.externel_processor_process.stop()

    return 0

def ignore_function(method: Optional[Callable] = None, tracer: Optional[VizTracer] = None) -> Callable:

    def inner(func: Callable) -> Callable:

        @functools.wraps(func)
        def ignore_wrapper(*args, **kwargs) -> Any:
            # We need this to keep trace a local variable
            t = tracer
            if not t:
                t = get_tracer()
                if not t:
                    raise NameError("ignore_function only works with global tracer")
            t.pause()
            ret = func(*args, **kwargs)
            t.resume()
            return ret

        return ignore_wrapper

    if method:
        return inner(method)
    return inner

def log_sparse(func: Optional[Callable] = None, stack_depth: int = 0) -> Callable:
    tracer = get_tracer()
    if tracer is None or not tracer.log_sparse:
        if func is None:
            return lambda f: f
        return func

    if func is None:
        def inner(dec_func: Callable) -> Callable:
            @functools.wraps(dec_func)
            def wrapper(*args, **kwargs) -> Any:
                assert isinstance(tracer, VizTracer)
                if not tracer.enable:
                    orig_max_stack_depth = tracer.max_stack_depth
                    tracer.max_stack_depth = stack_depth
                    tracer.start()
                    ret = dec_func(*args, **kwargs)
                    tracer.stop()
                    tracer.max_stack_depth = orig_max_stack_depth
                    return ret
                else:
                    return dec_func(*args, **kwargs)
            return wrapper
        return inner
    else:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            assert callable(func)
            assert isinstance(tracer, VizTracer)
            start = tracer.getts()
            ret = func(*args, **kwargs)
            dur = tracer.getts() - start
            code = func.__code__
            raw_data = {
                "ph": "X",
                "name": f"{code.co_name} ({code.co_filename}:{code.co_firstlineno})",
                "ts": start,
                "dur": dur,
                "cat": "FEE",
            }
            tracer.add_raw(raw_data)
            return ret

        return wrapper

def inner(func: Callable) -> Callable:

    @functools.wraps(func)
    def ignore_wrapper(*args, **kwargs) -> Any:
        # We need this to keep trace a local variable
        t = tracer
        if not t:
            t = get_tracer()
            if not t:
                raise NameError("ignore_function only works with global tracer")
        t.pause()
        ret = func(*args, **kwargs)
        t.resume()
        return ret

    return ignore_wrapper

def inner(dec_func: Callable) -> Callable:
    @functools.wraps(dec_func)
    def wrapper(*args, **kwargs) -> Any:
        assert isinstance(tracer, VizTracer)
        if not tracer.enable:
            orig_max_stack_depth = tracer.max_stack_depth
            tracer.max_stack_depth = stack_depth
            tracer.start()
            ret = dec_func(*args, **kwargs)
            tracer.stop()
            tracer.max_stack_depth = orig_max_stack_depth
            return ret
        else:
            return dec_func(*args, **kwargs)
    return wrapper

def wrapper(*args, **kwargs) -> Any:
    assert isinstance(tracer, VizTracer)
    if not tracer.enable:
        orig_max_stack_depth = tracer.max_stack_depth
        tracer.max_stack_depth = stack_depth
        tracer.start()
        ret = dec_func(*args, **kwargs)
        tracer.stop()
        tracer.max_stack_depth = orig_max_stack_depth
        return ret
    else:
        return dec_func(*args, **kwargs)

def triggerlog(method: Optional[Callable] = None, when: str = "after") -> Callable:
    if when not in ["after", "before", "both"]:
        raise ValueError(f"when has to be one of 'after', 'before' or 'both', not {when}")

    def inner(func: Callable) -> Callable:

        @functools.wraps(func)
        def wrapper(self, *args, **kwargs) -> Any:
            if when in ("before", "both"):
                self._viztracer_log()
            ret = func(self, *args, **kwargs)
            if when in ("after", "both"):
                self._viztracer_log()
            return ret
        return wrapper

    if method:
        return inner(method)
    return inner

def inner(func: Callable) -> Callable:

    @functools.wraps(func)
    def wrapper(self, *args, **kwargs) -> Any:
        if when in ("before", "both"):
            self._viztracer_log()
        ret = func(self, *args, **kwargs)
        if when in ("after", "both"):
            self._viztracer_log()
        return ret
    return wrapper

def wrapper(self, *args, **kwargs) -> Any:
    if when in ("before", "both"):
        self._viztracer_log()
    ret = func(self, *args, **kwargs)
    if when in ("after", "both"):
        self._viztracer_log()
    return ret

def trace_and_save(method: Optional[Callable] = None, output_dir: str = "./", **viztracer_kwargs):

    def inner(func: Callable) -> Callable:

        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            tracer = VizTracer(**viztracer_kwargs)
            tracer.start()
            ret = func(*args, **kwargs)
            tracer.stop()
            if not os.path.exists(output_dir):
                os.mkdir(output_dir)
            file_name = os.path.join(output_dir, f"result_{func.__name__}_{int(100000 * time.time())}.json")
            tracer.fork_save(file_name)
            tracer.cleanup()
            return ret

        return wrapper

    if method:
        return inner(method)
    return inner

def pause(self) -> None:
    if self.enable:
        self._tracer.pause()

def resume(self) -> None:
    if self.enable:
        self._tracer.resume()

def adopt(self, other: "FuncTreeNode") -> None:
    new_children = []
    if self.is_ancestor(other):
        # Build a list is slow
        # In almost all cases, end_idx should be the last, because that's
        # how we record entries.
        # In many cases, if two entries are siblings, start_idx is the
        # last too.
        # Try to skip building the list by checking these common situations
        # first.
        if not self.children:
            # if it's empty, then both indexes are 0
            start_idx = end_idx = 0
        else:
            if other.start > self.children[-1].start:
                start_idx = len(self.children)
            elif other.start < self.children[0].start:
                start_idx = 0
            else:
                start_array = [n.start for n in self.children]
                start_idx = bisect.bisect(start_array, other.start)
            if other.end > self.children[-1].end:
                end_idx = len(self.children)
            else:
                end_array = [n.end for n in self.children]
                end_idx = bisect.bisect(end_array, other.end)
        if (start_idx == end_idx + 1):
            self.children[end_idx].adopt(other)
        elif (start_idx == end_idx):
            other.parent = self
            self.children.insert(start_idx, other)
        elif (start_idx < end_idx):
            def change_parent(node):
                node.parent = other
            new_children = self.children[start_idx:end_idx]
            # force map to run
            list(map(change_parent, new_children))
            other.children = new_children
            other.parent = self
            self.children = self.children[:start_idx] + [other] + self.children[end_idx:]
        else:  # pragma: no cover
            raise Exception("This should not be possible")
    elif self.parent is not None:
        self.parent.adopt(other)
    else:  # pragma: no cover
        raise Exception("This should not be possible")

def node_by_timestamp(self, ts: float) -> FuncTreeNode:
    starts = [node.start for node in self.root.children]
    idx = bisect.bisect(starts, ts)
    if idx == 0:
        return self.root.children[0]
    else:
        return self.root.children[idx - 1]

def visit_Raise(self, node: ast.Raise) -> Union[ast.AST, List[ast.AST]]:
    if self.inst_type == "log_exception":
        instrument_node = self.get_instrument_node_by_node("Exception", node.exc)
        return [instrument_node, node]
    return node

def _visit_generic_assign(self, node: Union[ast.Assign, ast.AugAssign, ast.AnnAssign]) -> List[ast.stmt]:
    self.generic_visit(node)
    ret: List[ast.stmt] = [node]
    self.curr_lineno = node.lineno
    if self.inst_type in ("log_var", "log_number", "log_attr", "log_func_exec"):
        if isinstance(node, (ast.AugAssign, ast.AnnAssign)):
            instrumented_nodes = self.get_assign_log_nodes(node.target)
            if instrumented_nodes:
                ret.extend(instrumented_nodes)
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                instrumented_nodes = self.get_assign_log_nodes(target)
                if instrumented_nodes:
                    ret.extend(instrumented_nodes)
    return ret

def get_assign_targets(self, node: ast.expr) -> List[str]:
    """
    :param ast.Node node:
    """
    if isinstance(node, ast.Name):
        return [node.id]
    elif isinstance(node, (ast.Attribute, ast.Subscript, ast.Starred)):
        return self.get_assign_targets(node.value)
    elif isinstance(node, ast.Tuple) or isinstance(node, ast.List):
        return reduce(lambda a, b: a + b, [self.get_assign_targets(elt) for elt in node.elts])
    color_print("WARNING", "Unexpected node type {} for ast.Assign. \
        Please report to the author github.com/gaogaotiantian/viztracer".format(type(node)))
    return []

def get_assign_targets_with_attr(self, node: ast.AST) -> List[ast.Attribute]:
    """
    :param ast.Node node:
    """
    if isinstance(node, ast.Attribute):
        return [node]
    elif isinstance(node, (ast.Name, ast.Subscript, ast.Starred)):
        return []
    elif isinstance(node, (ast.Tuple, ast.List)):
        return reduce(lambda a, b: a + b, [self.get_assign_targets_with_attr(elt) for elt in node.elts])
    color_print("WARNING", "Unexpected node type {} for ast.Assign. \
        Please report to the author github.com/gaogaotiantian/viztracer".format(type(node)))
    return []

def get_assign_log_nodes(self, target: ast.expr) -> List[ast.stmt]:
    """
    given a target of any type of Assign, return the instrumented node
    that log this variable
    if this target is not supposed to be logged, return []
    """
    ret: List[ast.stmt] = []
    if self.inst_type in ("log_var", "log_number"):
        target_ids = self.get_assign_targets(target)
        for target_id in target_ids:
            for varname in self.inst_args["varnames"]:
                if re.fullmatch(varname, target_id):
                    ret.append(self.get_instrument_node("Variable Assign", target_id))
                    break
    elif self.inst_type == "log_attr":
        target_nodes = self.get_assign_targets_with_attr(target)
        for target_node in target_nodes:
            for varname in self.inst_args["varnames"]:
                if re.fullmatch(varname, target_node.attr):
                    ret.append(self.get_instrument_node_by_node("Attribute Assign", target_node))
                    break
    elif self.inst_type == "log_func_exec":
        if self.log_func_exec_enable:
            target_ids = self.get_assign_targets(target)
            for target_id in target_ids:
                ret.append(self.get_instrument_node("Variable Assign", target_id))

    return ret

def get_instrument_node(self, trigger: str, name: str) -> ast.Expr:
    if self.inst_type in ("log_var", "log_number"):
        if self.inst_type == "log_var":
            event = "instant"
        elif self.inst_type == "log_number":
            event = "counter"
        return self.get_add_variable_node(
            name=f"{trigger} - {name}",
            var_node=ast.Name(id=name, ctx=ast.Load()),
            event=event,
        )
    elif self.inst_type == "log_func_exec":
        return self.get_add_func_exec_node(
            name=f"{name}",
            val=ast.Name(id=name, ctx=ast.Load()),
            lineno=self.curr_lineno,
        )
    elif self.inst_type == "log_func_entry":
        return self.get_add_variable_node(
            name=f"{trigger} - {name}",
            var_node=ast.Constant(value=f"{name} is called"),
            event="instant",
        )
    else:
        raise ValueError(f"{name} is not supported")

def get_instrument_node_by_node(self, trigger: str, node: Optional[ast.expr]) -> ast.Expr:
    var_node: ast.expr
    if node is None:
        name = f"{trigger}"
        var_node = ast.Constant(value=None)
    else:
        name = f"{trigger} - {self.get_string_of_expr(node)}"
        var_node = self.copy_node_with_load(node)
    return self.get_add_variable_node(
        name=name,
        var_node=var_node,
        event="instant",
    )

def get_add_variable_node(self, name: str, var_node: ast.AST, event: str) -> ast.Expr:
    node_instrument = ast.Expr(
        value=ast.Call(
            func=ast.Attribute(
                value=ast.Name(id="__viz_tracer__", ctx=ast.Load()),
                attr="add_variable",
                ctx=ast.Load(),
            ),
            args=[
                ast.Constant(value=name),
                var_node,
                ast.Constant(value=event),
            ],
            keywords=[],
        ),
    )
    return node_instrument

def get_add_func_exec_node(self, name: str, val: ast.AST, lineno: int) -> ast.Expr:
    node_instrument = ast.Expr(
        value=ast.Call(
            func=ast.Attribute(
                value=ast.Name(id="__viz_tracer__", ctx=ast.Load()),
                attr="add_func_exec",
                ctx=ast.Load(),
            ),
            args=[
                ast.Constant(value=name),
                ast.Name(id=name, ctx=ast.Load()),
                ast.Constant(value=lineno),
            ],
            keywords=[],
        ),
    )
    return node_instrument

def normalize(self, first_ts: float) -> None:
    for node in self.inorder_traverse():
        node.start -= first_ts
        node.end -= first_ts

def do_GET(self):
    self.server.last_request = self.path
    self.server_thread.notify_active()
    self.directory = os.path.join(os.path.dirname(__file__), "web_dist")
    with chdir_temp(self.directory):
        return super().do_GET()

def end_headers(self):
    self.send_header('Access-Control-Allow-Origin', '*')
    self.send_header('Cache-Control', 'no-store')
    return super().end_headers()

def do_GET(self):
    if self.path.endswith("json"):
        # self.path starts with '/', we need to remove it
        self.send_response(302)
        self.send_header("Location", self.directory_viewer.get_link(self.path[1:]))
        self.end_headers()
    else:
        with chdir_temp(self.directory):
            super().do_GET()

def get_link(self, path: str) -> str:
    path = os.path.join(self.base_path, path)
    if path not in self.servers:
        self.servers[path] = self.create_server(path)

    server = self.servers[path]
    return server.link

