def add_func_args(self, key: str, value: Any) -> None:
    if self.enable:
        self._tracer.addfunctionarg(key, value)

def add_func_exec(self, name: str, val: Any, lineno: int) -> None:
    exec_line = f"({lineno}) {name} = {val}"
    curr_args = self._tracer.getfunctionarg()
    if not curr_args:
        self._tracer.addfunctionarg("exec_steps", [exec_line])
    else:
        if "exec_steps" in curr_args:
            curr_args["exec_steps"].append(exec_line)
        else:
            curr_args["exec_steps"] = [exec_line]

def __exit__(self, type, value, trace) -> None:
    dur = self._tracer.getts() - self.start
    raw_data = {
        "ph": "X",
        "name": f"{self.event_name} ({self.file_name}:{self.lineno})",
        "ts": self.start,
        "dur": dur,
        "cat": "FEE",
    }
    self._tracer.add_raw(raw_data)

def _wait_start(self):
    print("Loading and parsing trace data, this could take a while...")
    while True:
        line = self._process.stderr.readline().decode("utf-8")
        if "This server can be used" in line:
            break

def stop_attach() -> None:
    if attach_status.attached:
        tracer = get_tracer()
        if tracer:
            tracer.stop()
            tracer.save(attach_status.save_path)
            if tracer.verbose > 0:
                print(f"Saved report to {attach_status.save_path}", flush=True)
            attach_status.attached = False
            if attach_status.created_tracer:
                tracer.stop()
                attach_status.created_tracer = False
                builtins.__dict__.pop("__viz_tracer__")
                gc.collect()
        attach_status.attached = False

def clean_servers(self, force: bool = False) -> None:
    curr_time = time.time()
    removed_path = []
    for path, server in self.servers.items():
        if curr_time - server.last_active > self.timeout:
            if server.httpd is not None:
                server.httpd.shutdown()
            removed_path.append(path)
            server.join()
    for path in removed_path:
        self.servers.pop(path)
    if len(removed_path) == 0 and force:
        max_idle_time, max_idle_path = max(
            (curr_time - server.last_active, path)
            for path, server in self.servers.items()
        )
        server = self.servers.pop(max_idle_path)
        if server.httpd:
            server.httpd.shutdown()
        server.join()

def run(self) -> int:
    Handler = functools.partial(DirectoryHandler, self)
    socketserver.TCPServer.allow_reuse_address = True
    with VizViewerTCPServer(('0.0.0.0', self.port), Handler) as httpd:
        print("Running vizviewer")
        print(f"You can also view your trace on http://localhost:{self.port}")
        print("Press Ctrl+C to quit", flush=True)
        if not self.server_only:
            # import webbrowser only if necessary
            import webbrowser
            webbrowser.open_new_tab(f'http://127.0.0.1:{self.port}')
        try:
            httpd.serve_forever()
        except KeyboardInterrupt:
            for server in self.servers.values():
                if server.httpd:
                    server.httpd.shutdown()
                server.join()
            self.servers = {}
    return 0

def __init__(self, tracer: "VizTracer", plugins: Sequence[Union[VizPluginBase, str]]):
    self._tracer = tracer
    self._plugins = []
    for plugin in plugins:
        if isinstance(plugin, VizPluginBase):
            plugin_instance = plugin
        elif isinstance(plugin, str):
            plugin_instance = self._get_plugin_from_string(plugin)
        else:
            raise TypeError("Invalid plugin!")
        self._plugins.append(plugin_instance)

        support_version = plugin_instance.support_version()
        if compare_version(support_version, __version__) > 0:
            color_print("WARNING", "The plugin support version is higher than "
                                   "viztracer version. Consider update your viztracer")
        self._send_message(plugin_instance, "event", {"when": "initialize"})

def _get_plugin_from_string(self, plugin: str) -> VizPluginBase:
    args = plugin.split()
    module = args[0]
    try:
        package = __import__(module)
    except (ImportError):
        print(f"There's no module named {module}, maybe you need to install it")
        sys.exit(1)

    m = package
    if "." in module:
        # package.module
        names = module.split(".")

        try:
            for mod in names[1:]:
                m = m.__getattribute__(mod)
        except AttributeError:  # pragma: no cover
            # This in theory should never happen
            raise ImportError(f"Unable to import {module}, wrong path")
    try:
        m = m.__getattribute__("get_vizplugin")
    except AttributeError:
        print(f"Unable to find get_vizplugin in {module}. Incorrect plugin.")
        sys.exit(1)

    if callable(m):
        return m(plugin)
    else:
        print(f"Unable to find get_vizplugin as a callable in {module}. Incorrect plugin.")
        sys.exit(1)

def get_string_of_expr(self, node: Union[ast.expr, ast.slice]) -> str:
    """
    Try to do "unparse" of the node
    """
    if isinstance(node, ast.Name):
        return node.id
    elif isinstance(node, ast.Constant):
        if isinstance(node.value, str):
            return f"'{node.value}'"
        else:
            return f"{node.value}"
    elif isinstance(node, ast.Attribute):
        return f"{self.get_string_of_expr(node.value)}.{node.attr}"
    elif isinstance(node, ast.Subscript):
        return f"{self.get_string_of_expr(node.value)}[{self.get_string_of_expr(node.slice)}]"
    elif isinstance(node, ast.Call):
        return f"{self.get_string_of_expr(node.func)}()"
    elif isinstance(node, ast.Starred):
        return f"*{self.get_string_of_expr(node.value)}"
    elif isinstance(node, ast.Tuple):
        return f"({','.join([self.get_string_of_expr(elt) for elt in node.elts])})"
    elif isinstance(node, ast.List):
        return f"[{','.join([self.get_string_of_expr(elt) for elt in node.elts])}]"
    elif sys.version_info < (3, 9) and isinstance(node, ast.Index):
        return self.get_string_of_expr(node.value)
    elif isinstance(node, ast.Slice):
        lower = self.get_string_of_expr(node.lower) if "lower" in node._fields and node.lower else ""
        upper = self.get_string_of_expr(node.upper) if "upper" in node._fields and node.upper else ""
        step = self.get_string_of_expr(node.step) if "step" in node._fields and node.step else ""
        if step:
            return f"{lower}:{upper}:{step}"
        elif upper:
            return f"{lower}:{upper}"
        else:
            return f"{lower}:"
    elif sys.version_info < (3, 9) and isinstance(node, ast.ExtSlice):
        return ",".join([self.get_string_of_expr(dim) for dim in node.dims])
    color_print("WARNING", "Unexpected node type {} for ast.Assign. \
        Please report to the author github.com/gaogaotiantian/viztracer".format(type(node)))
    return ""

def color_print(color, s: str, **kwargs) -> None:
    if color_support:
        print(bcolors.__getattribute__(color) + s + bcolors.ENDC, **kwargs)
    else:  # pragma: no cover
        print(s)

def message(self, m_type: str, payload: Dict) -> Dict:
    """
    This is the only logical interface with VizTracer. To make it simple and flexible,
    we use m_type for message type, and the payload could be any json compatible
    data. This is more extensible in the future
    :param m_type str: the message type VizPlugin is receiving
    :param payload dict: payload of the message

    :return dict: always return a dict. Return None if nothing needs to be done
                  by VizTracer. Otherwise refer to the docs
    """
    if m_type == "command":
        if payload["cmd_type"] == "terminate":
            return {"success": True}

    return {}

def _send_message(self, plugin: VizPluginBase, m_type: str, payload: Dict) -> None:
    # this is the only interface to communicate with vizplugin
    # in the future we may need to do version compatibility
    # here
    support_version = plugin.support_version()

    ret = plugin.message(m_type, payload)
    if m_type == "command":
        self.assert_success(plugin, payload, ret)
    else:
        self.resolve(support_version, ret)

def command(self, cmd: Dict) -> None:
    for plugin in self._plugins:
        self._send_message(plugin, "command", cmd)

def terminate(self) -> None:
    self.command({"cmd_type": "terminate"})
    for plugin in self._plugins:
        del plugin
    self._plugins = []

def assert_success(self, plugin: VizPluginBase, cmd: Dict, ret: Optional[Dict]) -> None:
    if not ret or "success" not in ret or not ret["success"]:
        raise VizPluginError(f"{plugin} failed to process {cmd}")

def resolve(self, version: str, ret: Dict) -> None:
    if not ret or "action" not in ret:
        return
    if ret["action"] == "handle_data":
        ret["handler"](self._tracer.data)

def event(self, when: str) -> None:
    for plugin in self._plugins:
        self._send_message(plugin, "event", {"when": when})

def stop(self) -> None:
    if self.enable:
        _VizTracer.stop(self)
        self._plugin_manager.event("post-stop")

def save(
        self,
        output_file: Optional[str] = None,
        file_info: Optional[bool] = None,
        verbose: Optional[int] = None) -> None:
    if file_info is None:
        file_info = self.file_info
    enabled = False
    if output_file is None:
        output_file = self.output_file
    if verbose is None:
        verbose = self.verbose
    if self.pid_suffix:
        output_file_parts = output_file.split(".")
        output_file_parts[-2] = output_file_parts[-2] + "_" + str(os.getpid())
        output_file = ".".join(output_file_parts)

    if isinstance(output_file, str):
        output_file = os.path.abspath(output_file)
        if not os.path.isdir(os.path.dirname(output_file)):
            os.makedirs(os.path.dirname(output_file), exist_ok=True)

    if self.enable:
        enabled = True
        self.stop()

    # If there are plugins, we can't do dump raw because it will skip the data
    # manipulation phase
    if not self._plugin_manager.has_plugin and self.dump_raw:
        self.dump(output_file, sanitize_function_name=self.sanitize_function_name)
    else:
        if not self.parsed:
            self.parse()

        self._plugin_manager.event("pre-save")

        rb = ReportBuilder(self.data, verbose, minimize_memory=self.minimize_memory)
        rb.save(output_file=output_file, file_info=file_info)

    if self.viztmp is not None and os.path.exists(self.viztmp):
        os.remove(self.viztmp)

    if enabled:
        self.start()

def install(self) -> None:
    if sys.platform == "win32":
        print("remote install is not supported on Windows!")
        sys.exit(1)

    def signal_start(signum, frame):
        self.start()

    def signal_stop(signum, frame):
        self.stop()
        self.save()

    signal.signal(signal.SIGUSR1, signal_start)
    signal.signal(signal.SIGUSR2, signal_stop)

def signal_stop(signum, frame):
    self.stop()
    self.save()

def log_var(self, name: str, var: Any, cond: bool = True) -> None:
    if cond:
        if isinstance(var, (float, int)):
            self.add_counter(name, {"value": var})
        else:
            self.add_instant(name, args={"object": objprint.objstr(var, color=False)}, scope="t")

def log_gc(self, log_gc: bool) -> None:
    if isinstance(log_gc, bool):
        self.__log_gc = log_gc
        if log_gc:
            gc.callbacks.append(self.add_garbage_collection)
        elif self.add_garbage_collection in gc.callbacks:
            gc.callbacks.remove(self.add_garbage_collection)
    else:
        raise ValueError(f"log_gc needs to be True or False, not {log_gc}")

def add_instant(self, name: str, args: Any = None, scope: str = "g") -> None:
    if self.enable:
        if scope not in ["g", "p", "t"]:
            print("Scope has to be one of g, p, t")
            return
        self._tracer.addinstant(name, args, scope)

def add_variable(self, name: str, var: Any, event: str = "instant") -> None:
    if self.enable:
        if event == "instant":
            self.add_instant(f"{name} = {repr(var)}", scope="p")
        elif event == "counter":
            if isinstance(var, (int, float)):
                self.add_counter(name, {name: var})
            else:
                raise ValueError(f"{name}({var}) is not a number")
        else:
            raise ValueError(f"{event} is not supported")

def add_counter(self, name: str, args: Dict[str, Any]) -> None:
    if self.enable:
        self._tracer.addcounter(name, args)

def add_garbage_collection(self, phase: str, info: Dict[str, Any]) -> None:
    if self.enable:
        if phase == "start":
            args = {
                "collecting": 1,
                "collected": 0,
                "uncollectable": 0,
            }
            self.add_counter("garbage collection", args)
            self.gc_start_args = args
        if phase == "stop" and self.gc_start_args:
            self.gc_start_args["collected"] = info["collected"]
            self.gc_start_args["uncollectable"] = info["uncollectable"]
            self.gc_start_args = {}
            self.add_counter("garbage collection", {
                "collecting": 0,
                "collected": 0,
                "uncollectable": 0,
            })

def emit(self, record: LogRecord) -> None:
    if not self._tracer:
        return
    self._tracer.add_instant(f"logging - {self.format(record)}", scope="p")

def log_event(self, event_name: str) -> VizEvent:
    call_frame = sys._getframe(1)
    return VizEvent(self, event_name, call_frame.f_code.co_filename, call_frame.f_lineno)

def max_stack_depth(self, max_stack_depth: Union[str, int]) -> None:
    if isinstance(max_stack_depth, str):
        try:
            self.__max_stack_depth = int(max_stack_depth)
        except ValueError:
            raise ValueError(f"Error when trying to convert max_stack_depth {max_stack_depth} to integer.")
    elif isinstance(max_stack_depth, int):
        self.__max_stack_depth = max_stack_depth
    else:
        raise ValueError(f"Error when trying to convert max_stack_depth {max_stack_depth} to integer.")
    self.config()

