def start(self) -> None:
    self.enable = True
    self.parsed = False
    if self.log_print:
        self.overload_print()
    if self.include_files is not None and self.exclude_files is not None:
        raise Exception("include_files and exclude_files can't be both specified!")
    self.config()
    self._tracer.start()

