def stop(self) -> None:
    self.enable = False
    if self.log_print:
        self.restore_print()
    self._tracer.stop()

def parse(self) -> int:
    # parse() is also performance sensitive. We could have a lot of entries
    # in buffer, so try not to add any overhead when parsing
    # We parse the buffer into Chrome Trace Event Format
    self.stop()
    if not self.parsed:
        self.data = {
            "traceEvents": self._tracer.load(),
            "viztracer_metadata": {
                "version": __version__,
                "overflow": False,
            },
        }
        metadata_count = 0
        for d in self.data["traceEvents"]:
            if d["ph"] == "M":
                metadata_count += 1
            else:
                break
        self.total_entries = len(self.data["traceEvents"]) - metadata_count
        if self.total_entries == self.tracer_entries:
            self.data["viztracer_metadata"]["overflow"] = True
        self.parsed = True

    return self.total_entries

def add_object(self, ph: str, obj_id: str, name: str, args: Optional[Dict[str, Any]] = None) -> None:
    if self.enable:
        self._tracer.addobject(ph, obj_id, name, args)

def __init__(self, tracer: VizTracer, name: str, **kwargs) -> None:
    super().__init__(tracer, name, **kwargs)
    self._viztracer_id = str(id(self))
    if self._viztracer_tracer:
        self._viztracer_tracer.add_object("N", self._viztracer_id, self._viztracer_name)

def __del__(self) -> None:
    if self._viztracer_tracer:
        self._viztracer_tracer.add_object("D", self._viztracer_id, self._viztracer_name)

def size_fmt(num: Union[int, float], suffix: str = 'B') -> str:
    for unit in ['', 'Ki', 'Mi', 'Gi']:
        if abs(num) < 1024.0:
            return f"{num:3.1f}{unit}{suffix}"
        num /= 1024.0
    return f"{num:.1f}{'Ti'}{suffix}"

def visit_FunctionDef(self, node: ast.FunctionDef) -> ast.FunctionDef:
    if self.inst_type == "log_func_exec":
        for funcname in self.inst_args["funcnames"]:
            if re.fullmatch(funcname, node.name):
                self.log_func_exec_enable = True
    elif self.inst_type == "log_func_entry":
        for funcname in self.inst_args["funcnames"]:
            if re.fullmatch(funcname, node.name):
                node.body.insert(0, self.get_instrument_node("Function Entry", node.name))
    elif self.inst_type in ("log_var", "log_number"):
        instrumented_nodes: List[ast.stmt] = []
        args = node.args
        func_args_name = [a.arg for a in args.posonlyargs + args.args + args.kwonlyargs]
        if "vararg" in args._fields and args.vararg:
            func_args_name.append(args.vararg.arg)
        if "kwarg" in args._fields and args.kwarg:
            func_args_name.append(args.kwarg.arg)
        for name in func_args_name:
            for pattern in self.inst_args["varnames"]:
                if re.fullmatch(pattern, name):
                    instrumented_nodes.append(self.get_instrument_node("Variable Assign", name))
                    break

    self.generic_visit(node)

    if self.inst_type == "log_func_exec":
        self.log_func_exec_enable = False
    elif self.inst_type in ("log_var", "log_number") and instrumented_nodes:
        node.body = instrumented_nodes + node.body
    return node

def visit_For(self, node: ast.For) -> ast.For:
    if self.inst_type in ("log_var", "log_number"):
        instrumented_nodes = self.get_assign_log_nodes(node.target)

    self.generic_visit(node)

    if self.inst_type in ("log_var", "log_number"):
        if instrumented_nodes:
            node.body = instrumented_nodes + node.body
    return node

def process(self, source: Any):
    if isinstance(source, bytes):
        source = source.decode("utf-8")
    elif not isinstance(source, str):
        return source

    new_lines = []

    for line in source.splitlines():
        for pattern, transform in self.re_patterns:
            m = pattern.match(line)
            if m:
                new_lines.append(transform(self, m))
                break
        else:
            new_lines.append(line)

    return "\n".join(new_lines)

def compile(self, source, filename, mode, flags=0, dont_inherit=False, optimize=-1):
    if self.source_processor is not None:
        source = self.source_processor.process(source)
    if self.ast_transformers:
        tree = self._compile(source, filename, mode, flags | ast.PyCF_ONLY_AST, dont_inherit, optimize)
        for trans in self.ast_transformers:
            trans.visit(tree)
            ast.fix_missing_locations(tree)
        return self._compile(tree, filename, mode, flags, dont_inherit, optimize)

    return self._compile(source, filename, mode, flags, dont_inherit, optimize)

def inline_transform(self, re_match: re.Match) -> str:
    stmt = re_match.group(1)
    if "=" in stmt:
        val_assigned = stmt[:stmt.index("=")].strip()
        return f"{stmt}; __viz_tracer__.log_var('{val_assigned}', ({val_assigned}))"
    return f"{stmt}; __viz_tracer__.log_instant('{stmt.strip()}')"

def inline_transform_condition(self, re_match: re.Match) -> str:
    stmt = re_match.group(1)
    if "=" in stmt:
        val_assigned = stmt[:stmt.index("=")].strip()
        return f"{stmt}; __viz_tracer__.log_var('{val_assigned}', ({val_assigned}), cond={re_match.group(2)})"
    return f"{stmt}; __viz_tracer__.log_instant('{stmt.strip()}', cond={re_match.group(2)});"

def __setattr__(self, name: str, value: Any) -> None:
    self.__dict__[name] = value
    if not name.startswith("_"):
        if self._viztracer_enable and self._viztracer_config["trigger_on_change"]:
            if self._viztracer_config["include_attributes"]:
                if name in self._viztracer_config["include_attributes"]:
                    self._viztracer_log()
            elif self._viztracer_config["exclude_attributes"]:
                if name not in self._viztracer_config["exclude_attributes"]:
                    self._viztracer_log()
            else:
                self._viztracer_log()

def _create_win_event(name):
    from winappdbg.win32.kernel32 import CreateEventA, WaitForSingleObject, CloseHandle

    manual_reset = False  # i.e.: after someone waits it, automatically set to False.
    initial_state = False
    if not isinstance(name, bytes):
        name = name.encode('utf-8')
    event = CreateEventA(None, manual_reset, initial_state, name)
    if not event:
        raise ctypes.WinError()

    class _WinEvent(object):

        def wait_for_event_set(self, timeout=None):
            '''
            :param timeout: in seconds
            '''
            if timeout is None:
                timeout = 0xFFFFFFFF
            else:
                timeout = int(timeout * 1000)
            ret = WaitForSingleObject(event, timeout)
            if ret in (0, 0x80):
                return True
            elif ret == 0x102:
                # Timed out
                return False
            else:
                raise ctypes.WinError()

    try:
        yield _WinEvent()
    finally:
        CloseHandle(event)

def wait_for_event_set(self, timeout=None):
    '''
    :param timeout: in seconds
    '''
    if timeout is None:
        timeout = 0xFFFFFFFF
    else:
        timeout = int(timeout * 1000)
    ret = WaitForSingleObject(event, timeout)
    if ret in (0, 0x80):
        return True
    elif ret == 0x102:
        # Timed out
        return False
    else:
        raise ctypes.WinError()

def find_helper_script(filedir, script_name):
    target_filename = os.path.join(filedir, 'linux_and_mac', script_name)
    target_filename = os.path.normpath(target_filename)
    if not os.path.exists(target_filename):
        raise RuntimeError('Could not find helper script: %s' % target_filename)

    return target_filename
